fn solve(n: i8) -> bool {
    // Convert to a larger type for safe arithmetic (optional here)
    let x = n as i32;

    let d1 = x / 1000;           // thousands digit
    let d2 = (x / 100) % 10;     // hundreds digit
    let d3 = (x / 10) % 10;      // tens digit
    let d4 = x % 10;             // ones digit

    // Check if the first three digits are all equal
    let first_three_equal = d1 == d2 && d2 == d3;
    // Check if the last three digits are all equal
    let last_three_equal  = d2 == d3 && d3 == d4;

    first_three_equal || last_three_equal
}

